Procedure BeforeWrite(Cancel, WriteMode, PostingMode) {
    if (WriteMode = DocumentWriteMode.Posting And Not ValueIsFilled(Counterparty)) {
        Message("Fill the counterparty before posting.", StatusMessage.Error);
        Cancel = True;
    }
}

